<script setup>
import { computed,ref,watch,nextTick } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useDemo } from '../../stores/demo.js'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import RequiredInformation from '../../components/RequiredInformation.vue'
import {assessCase,caseRequirements,describeOperationalExceptions} from './reportRequirements.js'
import { printReport } from '../../lib/exports.js'
import { clone,incidentOptions,officeOptions,display } from './common.js'
const store=useDemo(),route=useRoute(),router=useRouter(),search=ref(''),status=ref(''),eventFilter=ref(route.query.eventId || ''),draft=ref(null),error=ref(''),success=ref('')
const actionTypes=['Show cause order','Notice / order','Decision','Penalty assessment','Penalty payment','Certificate suspension','Certificate lifting','SRB suspension','SRB lifting','Other']
const rows=computed(()=>store.visibleRecords('cases').filter(c=>(!eventFilter.value || c.eventId===eventFilter.value) && (!status.value || c.status===status.value) && `${c.caseNumber} ${c.party} ${c.violations}`.toLowerCase().includes((search.value || '').toLowerCase())))
const assessment=computed(()=>assessCase(draft.value||{}))
watch(assessment,value=>{for(const item of value.items)if(!item.missing)delete draft.value?.reportingExceptions?.[item.key]})
async function navigateRequirement(item){await nextTick();document.getElementById(item.step==='case-header'?'case-header':item.step)?.scrollIntoView({behavior:'smooth',block:'start'})}
const event=computed(()=>store.getEvent(draft.value?.eventId))
const columns=[{name:'caseNumber',label:'Case / incident',field:'caseNumber',align:'left',sortable:true},{name:'party',label:'Party / vessel',field:'party',align:'left',sortable:true},{name:'officeId',label:'Responsible office',field:'officeId',align:'left'},{name:'status',label:'Current outcome',field:'status',align:'left',sortable:true},{name:'penalty',label:'Penalty (PHP)',field:r=>r.penalty===null?'Unknown':r.penalty,align:'right'},{name:'actions',label:'',field:'id'}]
function load(){error.value='';success.value='';if(route.params.id){const record=store.visibleRecords('cases').find(c=>c.id===route.params.id);draft.value=record ? {...clone(record),reportingExceptions:clone(record.reportingExceptions||{})} : null}else if(route.query.new)create();else draft.value=null}
function create(){draft.value={eventId:eventFilter.value || route.query.eventId || '',caseNumber:'',vesselId:'',party:'',officeId:store.currentUser.value?.officeId || '',status:'ongoing_sco',violations:'',decision:'',decisionDate:'',penalty:null,paid:null,actions:[],reportingStatus:'draft',reportingExceptions:{}};error.value=''}
watch(()=>[route.params.id,route.query.new],load,{immediate:true})
watch(()=>store.visibleRecords('cases').map(c=>c.id).join('|'),()=>{if(route.params.id && !store.visibleRecords('cases').some(c=>c.id===route.params.id)){draft.value=null;error.value='This case is unavailable in your current account scope.'}})
function addAction(){draft.value.actions.push({id:`local-${Date.now()}-${draft.value.actions.length}`,type:'Show cause order',issuedDate:'',issuedTime:'',officeId:draft.value.officeId,reference:'',sourceTimeliness:'unknown',sourceRef:'',affectedDocument:'',relatedSuspension:'',surveyDetails:'',periodServed:'',conditionsMet:'',amount:null,conditions:'',notes:''})}
async function save(asDraft=false){try{if(!store.can('enforce',event.value))throw Error('Enforcement permission required.');if(!asDraft&&!assessment.value.ready){await nextTick();document.getElementById('case-required-information')?.scrollIntoView({behavior:'smooth',block:'start'});throw Error(`Address ${assessment.value.unresolved.length} required case/action item(s), including an explanation where information is Unknown / Not Applicable.`)}const data=clone(draft.value);data.reportingStatus=asDraft?'draft':'recorded';for(const key of ['penalty','paid']){data[key]=data[key]==='' || data[key]===null || data[key]===undefined ? null : Number(data[key]);if(data[key]!==null && (!Number.isFinite(data[key]) || data[key]<0))throw Error('Penalty and paid amounts must be non-negative or unknown.')}for(const action of data.actions||[])if(/penalty/i.test(action.type||'')){action.amount=action.amount===''||action.amount==null?null:Number(action.amount);if(action.amount!==null&&(!Number.isFinite(action.amount)||action.amount<0))throw Error('Action amounts must be non-negative or unknown.')}data.updatedAt=new Date().toISOString();data.createdAt ||=data.updatedAt;data.history ||= [];data.history.push({at:data.updatedAt,actorId:store.currentUser.value?.id,actorName:store.currentUser.value?.name,status:data.status,remarks:`Case saved; ${data.actions.length} recorded actions`});const result=data.id ? store.update('cases',data.id,data) : store.recordCase(data);draft.value=clone(result);success.value=asDraft?'Case draft saved.':'Case and action history saved.';if(!route.params.id)router.replace(`/admin/cases/${result.id}`)}catch(e){error.value=e.message}}
function preview(){const c=draft.value;printReport({title:`Enforcement case ${c.caseNumber}`,subtitle:'Demonstration / fictional data',metadata:{incident:event.value?.ref,office:c.officeId,status:c.status},sections:[{title:'Case particulars',content:`Party: ${display(c.party)}\nViolations: ${display(c.violations)}\nDecision: ${display(c.decision)}\nDecision date: ${display(c.decisionDate)}\nPenalty PHP: ${display(c.penalty)}\nPaid PHP: ${display(c.paid)}`},{title:'Orders and certificate / SRB actions',content:(c.actions||[]).map((a,i)=>`${i+1}. ${a.type} · ${display(a.reference)}\nIssued ${display(a.issuedDate)} ${a.issuedTime || 'Time unknown'} · ${display(a.officeId)}\nSource timeliness: ${display(a.sourceTimeliness)}\nConditions: ${display(a.conditions)}\nSource reference: ${display(a.sourceRef)}\nAffected document / person: ${display(a.affectedDocument)}\nRelated suspension: ${display(a.relatedSuspension)}\nSurvey warranting lifting: ${display(a.surveyDetails)}\nSRB period served: ${display(a.periodServed)}\nSRB compliance for lifting: ${display(a.conditionsMet)}\nAction amount PHP: ${display(a.amount)}\n${a.notes || ''}`).join('\n\n')},{title:'Case / Action Reporting Exceptions',content:describeOperationalExceptions(c,caseRequirements(c))}]})}
</script>
<template><div class="page-wrap"><PageHeader :title="draft ? (draft.caseNumber || 'New enforcement case') : 'Enforcement case register'" subtitle="Keep case outcomes, orders and certificate / SRB actions distinct from incident review."><template #actions><q-btn v-if="draft" outline no-caps label="Case register" to="/admin/cases" @click="draft=null"/><q-btn v-if="!draft" color="primary" no-caps icon="add" label="New case" @click="create"/><q-btn v-if="draft" outline no-caps icon="print" label="Preview case" @click="preview"/></template></PageHeader><q-banner v-if="error" class="bg-red-1 text-negative q-mb-md" rounded>{{error}}</q-banner><q-banner v-if="success" class="bg-green-1 text-positive q-mb-md" rounded>{{success}}</q-banner>
<template v-if="!draft && !route.params.id"><div class="panel toolbar-row q-mb-md"><q-input v-model="search" outlined dense clearable label="Search case, party or violation"/><q-select v-model="status" :options="['ongoing_sco','ongoing_penalty','dismissed','closed']" outlined dense clearable label="Case outcome" style="min-width:190px"/><q-select v-model="eventFilter" outlined dense clearable :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident" style="min-width:260px"/><q-space/><span class="muted">{{rows.length}} cases</span></div><div class="panel"><q-table flat :rows="rows" :columns="columns" row-key="id" :pagination="{rowsPerPage:10}"><template #body-cell-caseNumber="p"><q-td :props="p"><router-link class="record-link" :to="`/admin/cases/${p.row.id}`">{{p.row.caseNumber}}</router-link><div class="muted">{{store.getEvent(p.row.eventId)?.ref}}</div></q-td></template><template #body-cell-party="p"><q-td :props="p">{{p.row.party || 'Party unknown'}}<div class="muted">{{store.getEvent(p.row.eventId)?.vessels.find(v=>v.id===p.row.vesselId)?.name || 'Vessel not linked'}}</div></q-td></template><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.row.status"/></q-td></template><template #body-cell-actions="p"><q-td :props="p"><q-btn flat color="primary" no-caps label="Open case" :to="`/admin/cases/${p.row.id}`"/></q-td></template></q-table></div></template>
<q-form v-else-if="draft" @submit="save(false)"><div class="panel"><div class="section-title" id="case-header">Case particulars and outcome<q-chip v-if="draft.reportingStatus==='draft'" size="sm">Draft</q-chip></div><div class="form-grid"><q-input v-model="draft.caseNumber" outlined label="Case number *"/><q-select v-model="draft.eventId" @update:model-value="draft.vesselId=''" outlined :options="incidentOptions(store.visibleEvents.value)" emit-value map-options label="Related incident *"/><q-select v-model="draft.vesselId" outlined clearable :options="(event?.vessels || []).map(v=>({label:v.name,value:v.id}))" emit-value map-options label="Involved vessel"/><q-input v-model="draft.party" outlined label="Respondent / owner / operator *"/><q-select v-model="draft.officeId" outlined :options="officeOptions(store)" emit-value map-options label="Responsible office *"/><q-select v-model="draft.status" outlined :options="['ongoing_sco','ongoing_penalty','dismissed','closed']" label="Current case outcome *"/><q-input v-model="draft.violations" outlined type="textarea" label="Alleged violations and relevant provisions" class="span-2"/><q-input v-model="draft.decision" outlined type="textarea" label="Decision / disposition and rationale" class="span-2"/><q-input v-if="draft.decision||['closed','dismissed','ongoing_penalty'].includes(draft.status)" v-model="draft.decisionReference" outlined label="Decision / Order Reference *"/><q-input v-model="draft.decisionDate" outlined type="date" stack-label label="Decision date (blank if unknown)"/><q-input v-model="draft.penalty" outlined type="number" min="0" step="0.01" label="Assessed penalty PHP (blank = unknown)"/><q-input v-model="draft.paid" outlined type="number" min="0" step="0.01" label="Paid amount PHP (blank = unknown)"/></div></div>
<div class="panel q-mt-md"><div class="toolbar-row"><div><div class="section-title">Orders and actions</div><p class="muted q-mb-none">Add each SCO, order, decision, payment, suspension and lifting separately.</p></div><q-space/><q-btn outline no-caps icon="add" label="Add action" @click="addAction"/></div><q-banner class="q-my-md bg-blue-1 text-primary" rounded>Within / beyond 72H is a source-recorded category. No legal timing rule is inferred. Unknown occurrence or issue timestamps remain unknown.</q-banner><q-expansion-item v-for="(a,i) in draft.actions" :key="a.id" :id="`case-action:${a.id}`" :label="`${i+1}. ${a.type} · ${a.reference || 'Reference pending'}`" default-opened class="q-mb-md"><div class="form-grid q-pa-sm"><q-select v-model="a.type" outlined :options="actionTypes" label="Action type *"/><q-input v-model="a.reference" outlined label="Order / certificate / SRB reference *"/><q-input v-model="a.issuedDate" outlined type="date" stack-label label="Issue date (blank = unknown) *"/><q-input v-model="a.issuedTime" outlined type="time" stack-label label="Issue time (blank = unknown) *"/><q-select v-model="a.officeId" outlined :options="officeOptions(store)" emit-value map-options label="Actual issuing office *"/><q-select v-model="a.sourceTimeliness" outlined :options="[{label:'Unknown / not stated',value:'unknown'},{label:'Within 72H — recorded in source',value:'within_72h_source'},{label:'Beyond 72H — recorded in source',value:'beyond_72h_source'},{label:'Not applicable',value:'not_applicable'}]" emit-value map-options label="Source timeliness category *"/><q-input v-model="a.sourceRef" outlined label="Source Document / Copy Reference *"/>
 <template v-if="/certificate|srb/i.test(a.type)"><q-input v-model="a.affectedDocument" outlined label="Affected Certificate / SRB / Person *"/><q-input v-if="/lifting/i.test(a.type)" v-model="a.relatedSuspension" outlined label="Related Suspension Reference *"/><q-input v-if="/certificate/i.test(a.type)&&/lifting/i.test(a.type)" v-model="a.surveyDetails" outlined type="textarea" label="Survey Warranting Certificate Lifting *" class="span-2"/><template v-if="/srb/i.test(a.type)&&/lifting/i.test(a.type)"><q-input v-model="a.periodServed" outlined label="Period Lapsed / Served *"/><q-input v-model="a.conditionsMet" outlined type="textarea" label="Compliance Warranting SRB Lifting *" class="span-2"/></template></template><q-input v-if="/penalty/i.test(a.type)" v-model="a.amount" outlined type="number" min="0" step="0.01" label="Action Amount (PHP) *"/>
 <q-input v-model="a.conditions" outlined type="textarea" label="Conditions, affected document / person and lifting requirements" class="span-2"/><q-input v-model="a.notes" outlined type="textarea" label="Evidence / source reference and action remarks" class="span-2"/><q-btn flat color="negative" no-caps label="Remove unsaved action entry" @click="draft.actions.splice(i,1)"/></div></q-expansion-item><p v-if="!draft.actions.length" class="muted">No enforcement actions recorded. Add the first SCO or other action.</p></div><div class="panel q-mt-md" v-if="draft.history?.length"><div class="section-title">Case history</div><p v-for="(h,i) in [...draft.history].reverse()" :key="i" class="muted">{{h.at ? new Date(h.at).toLocaleString() : 'Time unknown'}} · {{h.actorName || h.actorId}} · {{h.status}} · {{h.remarks}}</p></div><RequiredInformation id="case-required-information" :assessment="assessment" :exceptions="draft.reportingExceptions" title="Required Case / Action Information" @navigate="navigateRequirement"/><p class="text-caption muted q-mt-sm">These completion checks support the recorded case and supplied MARINA outputs. Unknown dates/times need their source explanation; no legal timing rule is inferred.</p><div class="toolbar-row q-mt-md"><q-btn outline no-caps color="primary" label="Save draft" @click="save(true)"/><q-btn color="primary" no-caps icon="save" label="Save case and actions" type="submit"/><q-btn flat no-caps label="Open incident" :to="`/admin/incidents/${draft.eventId}`" :disable="!draft.eventId"/></div></q-form>
<section v-else class="panel"><h2>Case unavailable</h2><p>This case was not found or is unavailable to your account.</p><q-btn to="/admin/cases" color="primary" no-caps label="Case register"/></section></div></template>
